// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(uint256 seed) public {
        // Rule: for ANY input, calling owned() from the contract's current owner succeeds
        // (onlyOwner grants the owner access). The mutant reverts for the owner too.
        vm.prank(c.owner());
        bool ok;
        try c.owned() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "owned() must succeed for the current owner");
    }
}
